<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';$u=require_user($pdo);$errors=[];$success='';
$pdo->prepare('INSERT IGNORE INTO user_preferences(user_id) VALUES(?)')->execute([$u['id']]);
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$action=(string)($_POST['action']??'profile');
 if($action==='profile'){$display=trim((string)($_POST['display_name']??''));$bio=trim((string)($_POST['bio']??''));$website=trim((string)($_POST['website_url']??''));if($display==='')$errors[]='Display name is required.';if($website!==''&&!filter_var($website,FILTER_VALIDATE_URL))$errors[]='Website URL is invalid.';if(!$errors){$pdo->prepare('UPDATE users SET display_name=?,bio=?,website_url=? WHERE id=?')->execute([$display,$bio?:null,$website?:null,$u['id']]);$success='Profile updated.';}}
 if($action==='privacy'){$profile=in_array($_POST['profile_visibility']??'public',['public','private'],true)?$_POST['profile_visibility']:'public';$default=in_array($_POST['default_annotation_visibility']??'public',['public','team','private'],true)?$_POST['default_annotation_visibility']:'public';$presence=in_array($_POST['live_presence_mode']??'cloaked',['visible','team_only','cloaked','off'],true)?$_POST['live_presence_mode']:'cloaked';$search=isset($_POST['search_visibility'])?1:0;$pdo->prepare('UPDATE users SET live_presence_mode=? WHERE id=?')->execute([$presence,$u['id']]);$pdo->prepare('UPDATE user_preferences SET profile_visibility=?,search_visibility=?,default_annotation_visibility=? WHERE user_id=?')->execute([$profile,$search,$default,$u['id']]);$success='Privacy settings updated.';}
 if($action==='notifications'){$pdo->prepare('UPDATE user_preferences SET notify_social=?,notify_research=?,notify_sources=?,notify_live=? WHERE user_id=?')->execute([isset($_POST['notify_social'])?1:0,isset($_POST['notify_research'])?1:0,isset($_POST['notify_sources'])?1:0,isset($_POST['notify_live'])?1:0,$u['id']]);$success='Notification preferences updated.';}
 if($action==='password'){$new=(string)($_POST['new_password']??'');$current=(string)($_POST['current_password']??'');$q=$pdo->prepare('SELECT password_hash FROM users WHERE id=?');$q->execute([$u['id']]);$hash=$q->fetchColumn();if(strlen($new)<12)$errors[]='New password must be at least 12 characters.';elseif($hash&&!password_verify($current,(string)$hash))$errors[]='Current password is incorrect.';else{$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($new,PASSWORD_DEFAULT),$u['id']]);$success=$hash?'Password changed.':'Native password added.';}}
}
$q=$pdo->prepare("SELECT u.*,p.profile_visibility,p.search_visibility,p.default_annotation_visibility,p.notify_social,p.notify_research,p.notify_sources,p.notify_live FROM users u JOIN user_preferences p ON p.user_id=u.id WHERE u.id=?");$q->execute([$u['id']]);$s=$q->fetch();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Settings · Annotated</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/">Annotated</a><nav><a href="/home.php">Home</a><a href="/profile.php?u=<?=h($s['username'])?>">Profile</a><a href="/connected-accounts.php">Accounts</a><a href="/logout.php">Sign out</a></nav></header><main class="layout"><section><div class="pageTitle"><div class="eyebrow">ACCOUNT</div><h1>Settings</h1></div><?php foreach($errors as $e):?><div class="error"><?=h($e)?></div><?php endforeach?><?php if($success):?><div class="success"><?=h($success)?></div><?php endif?><div class="card"><h2>Profile</h2><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="profile"><label>Display name<input name="display_name" value="<?=h($s['display_name'])?>" required></label><label>Bio<textarea name="bio" rows="5" maxlength="2000"><?=h($s['bio'])?></textarea></label><label>Website<input type="url" name="website_url" value="<?=h($s['website_url'])?>"></label><button>Save profile</button></form></div><div class="card"><h2>Privacy & publishing</h2><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="privacy"><label>Profile visibility<select name="profile_visibility"><option value="public" <?=$s['profile_visibility']==='public'?'selected':''?>>Public</option><option value="private" <?=$s['profile_visibility']==='private'?'selected':''?>>Private</option></select></label><label><input type="checkbox" name="search_visibility" value="1" <?=$s['search_visibility']?'checked':''?>> Allow my profile to appear in search</label><label>Default annotation visibility<select name="default_annotation_visibility"><option value="public" <?=$s['default_annotation_visibility']==='public'?'selected':''?>>Public</option><option value="team" <?=$s['default_annotation_visibility']==='team'?'selected':''?>>Team</option><option value="private" <?=$s['default_annotation_visibility']==='private'?'selected':''?>>Private</option></select></label><label>Live presence<select name="live_presence_mode"><option value="visible" <?=$s['live_presence_mode']==='visible'?'selected':''?>>Visible</option><option value="team_only" <?=$s['live_presence_mode']==='team_only'?'selected':''?>>Team only</option><option value="cloaked" <?=$s['live_presence_mode']==='cloaked'?'selected':''?>>Cloaked</option><option value="off" <?=$s['live_presence_mode']==='off'?'selected':''?>>Off</option></select></label><button>Save privacy settings</button></form></div><div class="card"><h2>Notifications</h2><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="notifications"><?php foreach(['social'=>'Social activity','research'=>'Research activity','sources'=>'Source changes','live'=>'Live mentions'] as $key=>$label):?><label><input type="checkbox" name="notify_<?=$key?>" value="1" <?=$s['notify_'.$key]?'checked':''?>> <?=h($label)?></label><?php endforeach?><button>Save notification settings</button></form></div><div class="card"><h2><?=empty($s['password_hash'])?'Add native password':'Change password'?></h2><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="password"><?php if(!empty($s['password_hash'])):?><label>Current password<input type="password" name="current_password" required></label><?php endif?><label>New password<input type="password" name="new_password" minlength="12" required></label><button><?=empty($s['password_hash'])?'Add password':'Change password'?></button></form></div></section><aside><div class="card"><h3>Account security</h3><p class="meta">Manage Google/X connections and revoke Chrome extension sessions.</p><a class="button secondary" href="/connected-accounts.php">Connected accounts</a></div></aside></main></body></html>
